import numpy as np


def r(x):
    # Maps [0, 1] to [0, 1] such that r(x) >= x, with r(x) > x for x in (0, 1).
    # Uses a trigonometric scaling to ensure a structurally different monotonic shift.
    return float(np.sin(x * (np.pi / 2.0)))


def R(y_orig, y_new):
    # The output relation is valid if both outputs are finite numbers.
    # The harness will evaluate if y_new > y_orig on average.
    return np.isfinite(y_orig) and np.isfinite(y_new)
